import{_ as e,c as t,o as p,a3 as r}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"常見問題（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/faq.md","filePath":"zh-TW/guide/faq.md","lastUpdated":1786597585000}'),o={name:"zh-TW/guide/faq.md"};function n(s,a,i,c,l,g){return p(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="常見問題-faq" tabindex="-1">常見問題（FAQ） <a class="header-anchor" href="#常見問題-faq" aria-label="Permalink to &quot;常見問題（FAQ）&quot;">​</a></h1><p><strong>Q: 什麼是 ClipboardxAI？</strong></p><p>A: ClipboardxAI 是一款專為 macOS 打造的智慧剪貼簿管理工具。它會保存你所有複製內容的可搜尋歷史紀錄，並讓你對其執行動作——摘要、翻譯、整理文字，或是傳送給雲端 AI 模型。</p><p><strong>Q: 支援哪些 macOS 版本？</strong></p><p>A: macOS 14 Sonoma 或以上版本，針對 Apple Silicon（M 系列）最佳化，同時支援 Intel。</p><p><strong>Q: 如何安裝？</strong></p><p>A: 請從 <a href="/zh-TW/">Mac App Store</a>（推薦）下載，或從 <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a> 取得最新的建置版本。請參見<a href="/zh-TW/guide/installation.html">安裝指南</a>。</p><p><strong>Q: ClipboardxAI 是免費的嗎？</strong></p><p>A: ClipboardxAI 是 Mac App Store 上的付費應用程式。購買後所有內建本地工具均已包含，不需要帳號。雲端 AI 動作使用<em>你自己的</em>供應商 API key，費用直接支付給 AI 供應商——應用程式內無需額外付費。</p><p><strong>Q: 支援哪些 AI 供應商？</strong></p><p>A: 任何 OpenAI 相容的供應商：DeepSeek、MiniMax、Zhipu GLM、Kimi (Moonshot)、Mistral，以及本地 Ollama——另外還有 OpenAI、Anthropic 與 Gemini。你的 key 會儲存在 Keychain 中。</p><p><strong>Q: 它可以離線運作嗎？</strong></p><p>A: 可以。剪貼簿歷史與內建本地工具（擷取連結、統計計數、摺疊空白行等）完全在你的 Mac 上執行，不需要網際網路連線。</p><p><strong>Q: 我的剪貼簿資料私密嗎？</strong></p><p>A: 你的歷史紀錄保留在你的裝置上。雲端 AI 為可選功能，且只會使用來自你 Keychain 的 key，將內容傳送給你所設定的供應商。我們絕不接收或儲存你的剪貼內容，也不會進行任何遙測。請參見<a href="/zh-TW/guide/privacy.html">隱私權政策</a>。</p><p><strong>Q: 如何加入更多動作？</strong></p><p>A: 瀏覽 <a href="/zh-TW/marketplace/">Marketplace</a>，並點擊任何動作上的 <strong>Install（安裝）</strong>。它會透過深層連結開啟應用程式，並出現在你的<strong>已安裝</strong>清單中。</p><p><strong>Q: 如何更新應用程式？</strong></p><p>A: Mac App Store 版本會自動更新。若是 GitHub 版本，請下載最新的 release 並替換 <code>Applications</code> 中的應用程式。</p><p><strong>Q: 如何回報錯誤或提出功能建議？</strong></p><p>A: 請在 <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub 儲存庫</a> 開啟一個 issue。請包含你的 macOS 版本、應用程式版本，以及重現步驟。</p><p><strong>Q: 我的資料儲存在哪裡？</strong></p><p>A: 位於沙箱容器中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.clipboard/Data/Library/Application Support/com.w3cub.clipboard/</span></span></code></pre></div><p>API key 位於系統 Keychain 中，不在該資料夾內。</p>',25)])])}const A=e(o,[["render",n]]);export{h as __pageData,A as default};
